ARCHIVOS["frontend/kiosko_turnos.html"] = [
    [
        "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\" />\n<title>Tomar turno</title>\n<style>\n  * { box-sizing: border-box; }\n  html, body { margin:0; padding:0; height:100%; background:#0B0C0D; color:#EDEDED; font-family:'IBM Plex Sans','Segoe UI',sans-serif; }\n  body { display:flex; align-items:center; justify-content:center; text-align:center; padding:24px; }\n  #caja { max-width:420px; width:100%; }\n  h1 { font-size:24px; margin:0 0 6px; }\n  .sub { font-size:14px; color:#9B9D9F; margin-bottom:32px; }\n  #btnTomar { width:100%; padding:28px; font-size:22px; font-weight:700; border-radius:14px; border:none; background:#D8192F; color:#fff; cursor:pointer; }\n  #btnTomar:active { transform: scale(0.98); }\n  #btnTomar:disabled { opacity:0.5; }\n  #resultado { display:none; }\n  #resultado .numero { font-size:96px; font-weight:800; margin:16px 0; }\n  #resultado .nota { font-size:14px; color:#9B9D9F; margin-bottom:28px; }\n  #btnOtro { padding:14px 24px; font-size:14px; border-radius:10px; border:1px solid rgba(155,157,159,0.35); background:transparent; color:#EDEDED; cursor:pointer; }\n  #mensajeError { font-size:13px; color:#FF6B7A; min-height:18px; margin-top:14px; }\n</style>\n</head>\n<body>\n\n<div id=\"caja\">\n  <div id=\"pantallaInicial\">\n    <h1>🎫 Tomar turno</h1>\n    <div class=\"sub\">Presiona el botón para sacar tu turno</div>\n    <button id=\"btnTomar\" onclick=\"tomarTurno()\">Tomar turno</button>\n    <div id=\"mensajeError\"></div>\n  </div>\n  <div id=\"resultado\">\n    <div class=\"sub\">Tu turno es</div>\n    <div class=\"numero\" id=\"numeroTurno\">—</div>\n    <div class=\"nota\">Espera a que te llamemos en la pantalla</div>\n    <button id=\"btnOtro\" onclick=\"volverAInicio()\">Tomar otro turno</button>\n  </div>\n</div>\n\n<script>\n  // Página PÚBLICA (sin login) -- se deja abierta en la tablet/PC de\n  // entrada de la sucursal. El código se lee de la URL y solo sirve para\n  // pedir /api/turnos/kiosko/{codigo}/tomar; no guarda nada del cliente.\n  const codigo = window.location.pathname.split('/').filter(Boolean).pop();\n\n  async function tomarTurno() {\n    const boton = document.getElementById('btnTomar');\n    boton.disabled = true;\n    document.getElementById('mensajeError').textContent = '';\n    try {\n      const resp = await fetch(`/api/turnos/kiosko/${codigo}/tomar`, { method: 'POST' });\n      if (!resp.ok) {\n        const err = await resp.json().catch(() => ({}));\n        throw new Error(err.detail || 'No se pudo tomar el turno.');\n      }\n      const datos = await resp.json();\n      document.getElementById('numeroTurno').textContent = `#${datos.numero}`;\n      document.getElementById('pantallaInicial').style.display = 'none';\n      document.getElementById('resultado').style.display = 'block';\n    } catch (e) {\n      document.getElementById('mensajeError').textContent = e.message || 'Este kiosko no es válido.';\n    } finally {\n      boton.disabled = false;\n    }\n  }\n\n  function volverAInicio() {\n    document.getElementById('resultado').style.display = 'none';\n    document.getElementById('pantallaInicial').style.display = 'block';\n  }\n</script>\n</body>\n</html>\n",
        "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\" />\n<title>Tomar turno</title>\n<style>\n  * { box-sizing: border-box; }\n  html, body { margin:0; padding:0; height:100%; background:#0B0C0D; color:#EDEDED; font-family:'IBM Plex Sans','Segoe UI',sans-serif; }\n  body { display:flex; align-items:center; justify-content:center; text-align:center; padding:24px; }\n  #caja { max-width:420px; width:100%; }\n  h1 { font-size:24px; margin:0 0 6px; }\n  .sub { font-size:14px; color:#9B9D9F; margin-bottom:32px; }\n  #btnTomar { width:100%; padding:28px; font-size:22px; font-weight:700; border-radius:14px; border:none; background:#D8192F; color:#fff; cursor:pointer; }\n  #btnTomar:active { transform: scale(0.98); }\n  #btnTomar:disabled { opacity:0.5; }\n  #botonesCategorias { display:none; grid-template-columns: 1fr 1fr; gap:14px; margin-bottom:14px; }\n  .btnCategoria { padding:26px 10px; font-size:17px; font-weight:700; border-radius:14px; border:none; background:#D8192F; color:#fff; cursor:pointer; }\n  .btnCategoria:active { transform: scale(0.98); }\n  .btnCategoria:disabled { opacity:0.5; }\n  #resultado { display:none; }\n  #resultado .numero { font-size:96px; font-weight:800; margin:16px 0; }\n  #resultado .nota { font-size:14px; color:#9B9D9F; margin-bottom:28px; }\n  #btnOtro { padding:14px 24px; font-size:14px; border-radius:10px; border:1px solid rgba(155,157,159,0.35); background:transparent; color:#EDEDED; cursor:pointer; }\n  #mensajeError { font-size:13px; color:#FF6B7A; min-height:18px; margin-top:14px; }\n</style>\n</head>\n<body>\n\n<div id=\"caja\">\n  <div id=\"pantallaInicial\">\n    <h1>🎫 Tomar turno</h1>\n    <div class=\"sub\" id=\"subInicial\">Presiona el botón para sacar tu turno</div>\n    <div id=\"botonesCategorias\"></div>\n    <button id=\"btnTomar\" onclick=\"tomarTurno()\">Tomar turno</button>\n    <div id=\"mensajeError\"></div>\n  </div>\n  <div id=\"resultado\">\n    <div class=\"sub\">Tu turno es</div>\n    <div class=\"numero\" id=\"numeroTurno\">—</div>\n    <div class=\"nota\">Espera a que te llamemos en la pantalla</div>\n    <button id=\"btnOtro\" onclick=\"volverAInicio()\">Tomar otro turno</button>\n  </div>\n</div>\n\n<script>\n  // Página PÚBLICA (sin login) -- se deja abierta en la tablet/PC de\n  // entrada de la sucursal. El código se lee de la URL y solo sirve para\n  // pedir /api/turnos/kiosko/{codigo}/tomar; no guarda nada del cliente.\n  const codigo = window.location.pathname.split('/').filter(Boolean).pop();\n  let enviando = false;\n\n  function escapeHtml(s) {\n    return String(s).replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n  }\n\n  async function cargarCategorias() {\n    // Si la sucursal configuró categorías (Compras, Laboratorio, etc.),\n    // se muestran como botones grandes en vez del botón sencillo. Si no\n    // configuró ninguna (o falla la carga), se queda como estaba.\n    try {\n      const resp = await fetch(`/api/turnos/kiosko/${codigo}/categorias`);\n      if (!resp.ok) return;\n      const categorias = await resp.json();\n      if (!categorias.length) return;\n      document.getElementById('btnTomar').style.display = 'none';\n      document.getElementById('subInicial').textContent = 'Elige el motivo de tu visita';\n      const cont = document.getElementById('botonesCategorias');\n      cont.style.display = 'grid';\n      cont.innerHTML = categorias.map(c => `<button class=\"btnCategoria\" onclick=\"tomarTurno(${c.id})\">${escapeHtml(c.nombre)}</button>`).join('');\n    } catch (e) { /* si falla, se queda con el botón sencillo */ }\n  }\n\n  async function tomarTurno(categoriaId) {\n    if (enviando) return;\n    enviando = true;\n    document.getElementById('btnTomar').disabled = true;\n    document.querySelectorAll('.btnCategoria').forEach(b => b.disabled = true);\n    document.getElementById('mensajeError').textContent = '';\n    try {\n      const resp = await fetch(`/api/turnos/kiosko/${codigo}/tomar`, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ categoria_id: categoriaId || null }),\n      });\n      if (!resp.ok) {\n        const err = await resp.json().catch(() => ({}));\n        throw new Error(err.detail || 'No se pudo tomar el turno.');\n      }\n      const datos = await resp.json();\n      document.getElementById('numeroTurno').textContent = `#${datos.folio || datos.numero}`;\n      document.getElementById('pantallaInicial').style.display = 'none';\n      document.getElementById('resultado').style.display = 'block';\n    } catch (e) {\n      document.getElementById('mensajeError').textContent = e.message || 'Este kiosko no es válido.';\n    } finally {\n      enviando = false;\n      document.getElementById('btnTomar').disabled = false;\n      document.querySelectorAll('.btnCategoria').forEach(b => b.disabled = false);\n    }\n  }\n\n  function volverAInicio() {\n    document.getElementById('resultado').style.display = 'none';\n    document.getElementById('pantallaInicial').style.display = 'block';\n  }\n\n  cargarCategorias();\n</script>\n</body>\n</html>\n",
    ],
]

