        "let MKT_SUCURSAL_ELEGIDA = null;\n\nasync function abrirMarketing() {",
        "let MKT_SUCURSAL_ELEGIDA = null;\nlet MKT_TURNOS_PRESET = 'semana';\nlet MKT_TURNOS_SUCURSAL_ID = '';\nlet MKT_TURNOS_CHART = null;\n\nasync function abrirMarketing() {",
