        "async function quitarVideoSucursalMarketingUI(boton) {\n  const url = boton.dataset.url;\n  if (!confirm('¿Quitar este video de esta sucursal? (el video sigue disponible en la lista para volver a usarlo después)')) return;\n  try {\n    await api(`/api/reparaciones/sucursales/${MKT_SUCURSAL_ELEGIDA}/turnos/videos/quitar`, { method: 'POST', body: JSON.stringify({ url }) });\n    mostrarExito('Video quitado');\n    await renderVideosTurnosMarketing();\n  } catch (e) {\n    alert(e.message);\n  }\n}\n\n\n\nfunction abrirCrearProyecto() {",
        "async function quitarVideoSucursalMarketingUI(boton) {\n  const url = boton.dataset.url;\n  if (!confirm('¿Quitar este video de esta sucursal? (el video sigue disponible en la lista para volver a usarlo después)')) return;\n  try {\n    await api(`/api/reparaciones/sucursales/${MKT_SUCURSAL_ELEGIDA}/turnos/videos/quitar`, { method: 'POST', body: JSON.stringify({ url }) });\n    mostrarExito('Video quitado');\n    await renderVideosTurnosMarketing();\n  } catch (e) {\n    alert(e.message);\n  }\n}\n\n// -- Reporte de Turnos (registro diario + gráfica comparando sucursales) --\n\nfunction calcularPresetFechasTurnos(preset) {\n  const hoy = new Date();\n  const formatoFecha = (d) => d.toISOString().slice(0, 10);\n  if (preset === 'mes') {\n    const primerDia = new Date(hoy.getFullYear(), hoy.getMonth(), 1);\n    const ultimoDia = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);\n    return { desde: formatoFecha(primerDia), hasta: formatoFecha(ultimoDia) };\n  }\n  if (preset === 'anio') {\n    return { desde: `${hoy.getFullYear()}-01-01`, hasta: `${hoy.getFullYear()}-12-31` };\n  }\n  // 'semana' -- lunes a domingo de esta semana\n  const diaSemana = hoy.getDay() === 0 ? 7 : hoy.getDay();\n  const lunes = new Date(hoy); lunes.setDate(hoy.getDate() - diaSemana + 1);\n  const domingo = new Date(lunes); domingo.setDate(lunes.getDate() + 6);\n  return { desde: formatoFecha(lunes), hasta: formatoFecha(domingo) };\n}\n\nasync function renderReporteTurnosMarketing() {\n  const cont = document.getElementById('marketingContenido');\n  cont.innerHTML = '<p style=\"font-size:12px; color:var(--muted);\">Cargando…</p>';\n  const sucursales = await api('/api/reparaciones/sucursales');\n  MKT_SUCURSALES_CACHE = sucursales;\n  const rango = calcularPresetFechasTurnos(MKT_TURNOS_PRESET);\n  const qs = new URLSearchParams({ desde: rango.desde, hasta: rango.hasta });\n  if (MKT_TURNOS_SUCURSAL_ID) qs.set('sucursal_id', MKT_TURNOS_SUCURSAL_ID);\n  const filas = await api(`/api/marketing/turnos/reporte?${qs.toString()}`);\n  cont.innerHTML = `\n    <p style=\"font-size:12px; color:var(--muted); margin-bottom:10px;\">Cuántos turnos se tomaron cada día, con desglose por categoría, y qué sucursal tiene más movimiento.</p>\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin-bottom:14px;\">\n      <select id=\"mktTurnosPreset\" onchange=\"MKT_TURNOS_PRESET = this.value; renderReporteTurnosMarketing();\">\n        <option value=\"semana\" ${MKT_TURNOS_PRESET === 'semana' ? 'selected' : ''}>Esta semana</option>\n        <option value=\"mes\" ${MKT_TURNOS_PRESET === 'mes' ? 'selected' : ''}>Este mes</option>\n        <option value=\"anio\" ${MKT_TURNOS_PRESET === 'anio' ? 'selected' : ''}>Este año</option>\n      </select>\n      <select id=\"mktTurnosSucursal\" onchange=\"MKT_TURNOS_SUCURSAL_ID = this.value; renderReporteTurnosMarketing();\">\n        <option value=\"\">Todas las sucursales</option>\n        ${sucursales.map(s => `<option value=\"${s.id}\" ${String(s.id) === String(MKT_TURNOS_SUCURSAL_ID) ? 'selected' : ''}>${escapeHtml(s.nombre)}</option>`).join('')}\n      </select>\n      <span style=\"font-size:12px; color:var(--muted);\">${rango.desde} a ${rango.hasta}</span>\n    </div>\n    <div style=\"background:var(--panel-2); border-radius:8px; padding:14px; margin-bottom:16px;\">\n      <canvas id=\"mktTurnosChart\" height=\"90\"></canvas>\n    </div>\n    <table class=\"users\">\n      <thead><tr><th>Fecha</th><th>Sucursal</th><th>Categoría</th><th>Turnos</th></tr></thead>\n      <tbody>\n        ${filas.map(f => `\n          <tr><td>${f.fecha}</td><td>${escapeHtml(f.sucursal_nombre)}</td><td>${escapeHtml(f.categoria)}</td><td>${f.total}</td></tr>\n        `).join('') || '<tr><td colspan=\"4\" class=\"empty-col\">— sin turnos en este periodo —</td></tr>'}\n      </tbody>\n    </table>\n  `;\n  dibujarGraficaTurnosMarketing(filas, rango);\n}\n\nfunction dibujarGraficaTurnosMarketing(filas, rango) {\n  const canvas = document.getElementById('mktTurnosChart');\n  if (!canvas || typeof Chart === 'undefined') return;\n  const estilos = getComputedStyle(document.documentElement);\n  const colorTexto = (estilos.getPropertyValue('--text') || '#F2F1F0').trim();\n  const colorMuted = (estilos.getPropertyValue('--trace') || '#9B9D9F').trim();\n  // Total por sucursal y fecha, sumando todas las categorías -- para\n  // comparar quién tiene más movimiento en total, no por categoría.\n  const porSucursal = {};\n  filas.forEach(f => {\n    if (!porSucursal[f.sucursal_nombre]) porSucursal[f.sucursal_nombre] = {};\n    porSucursal[f.sucursal_nombre][f.fecha] = (porSucursal[f.sucursal_nombre][f.fecha] || 0) + f.total;\n  });\n  const fechas = [];\n  for (let d = new Date(rango.desde + 'T00:00:00'); d <= new Date(rango.hasta + 'T00:00:00'); d.setDate(d.getDate() + 1)) {\n    fechas.push(d.toISOString().slice(0, 10));\n  }\n  const paleta = ['#D8192F', '#2E7DD1', '#2FA84F', '#E0A62E', '#8E5FD1', '#D1638E', '#4FB8B0', '#B08B4F'];\n  const datasets = Object.keys(porSucursal).sort().map((nombre, i) => ({\n    label: nombre,\n    data: fechas.map(f => porSucursal[nombre][f] || 0),\n    borderColor: paleta[i % paleta.length],\n    backgroundColor: paleta[i % paleta.length],\n    tension: 0.25,\n    pointRadius: 3,\n  }));\n  if (MKT_TURNOS_CHART) { MKT_TURNOS_CHART.destroy(); MKT_TURNOS_CHART = null; }\n  if (!datasets.length) return;\n  MKT_TURNOS_CHART = new Chart(canvas, {\n    type: 'line',\n    data: { labels: fechas, datasets },\n    options: {\n      responsive: true,\n      plugins: { legend: { labels: { color: colorTexto } } },\n      scales: {\n        x: { ticks: { color: colorMuted }, grid: { color: 'rgba(155,157,159,0.15)' } },\n        y: { beginAtZero: true, ticks: { color: colorMuted, precision: 0 }, grid: { color: 'rgba(155,157,159,0.15)' } },\n      },\n    },\n  });\n}\n\n\n\nfunction abrirCrearProyecto() {",
